SELECT

FROM sys_message




      AND user_id = #{query.userId}
      AND broadcast_role IS NULL



      AND user_id = #{currentId}
      AND broadcast_role IS NULL



      AND (user_id = #{currentId} OR broadcast_role = 1)




    AND type = #{query.type}


    AND target_type = #{query.targetType}


    AND is_read = #{query.isRead}


    AND (
    title LIKE CONCAT('%', #{query.keyword}, '%')
    OR content LIKE CONCAT('%', #{query.keyword}, '%')
    )


ORDER BY is_read ASC, created_at DESC, id DESC
